-- ============================================
-- LUMA — Thème 6 : LONG 3/3 x4 — Un déménagement collectif à planifier
-- ============================================


update scenarios set content = '{"characters": {"roommate1": "Colocataire 1", "roommate2": "Colocataire 2", "agent": "l''agent immobilier"}, "start_node": "n1", "nodes": {"n1": {"speaker": "roommate1", "text": "Okay, so the lease is up in two months. Should we start looking for a new place together?", "text_fr": "Bon, le bail se termine dans deux mois. On devrait commencer à chercher un nouvel endroit ensemble ?", "choices": [{"text": "Yes, I think we work well together, let''s find something bigger.", "text_fr": "Oui, je pense qu''on se débrouille bien ensemble, cherchons quelque chose de plus grand.", "next": "n2"}, {"text": "I''m open to it, though we should agree on budget first.", "text_fr": "Je suis ouvert à ça, même si on devrait se mettre d''accord sur le budget d''abord.", "next": "n2b"}]}, "n2": {"speaker": "roommate2", "text": "Agreed, I''ll start browsing listings tonight. Any must-haves?", "text_fr": "D''accord, je vais commencer à parcourir les annonces ce soir. Des critères indispensables ?", "choices": [{"text": "A washer and dryer in-unit would be amazing.", "text_fr": "Une machine à laver et sèche-linge dans l''appart serait génial.", "next": "n3"}, {"text": "Close to public transit is my top priority.", "text_fr": "Proche des transports en commun c''est ma priorité.", "next": "n3"}]}, "n2b": {"speaker": "roommate1", "text": "Good call. What''s everyone comfortable spending, roughly?", "text_fr": "Bonne idée. Combien tout le monde est à l''aise de dépenser, à peu près ?", "choices": [{"text": "I could do up to $900 a month for my share.", "text_fr": "Je pourrais faire jusqu''à 900$ par mois pour ma part.", "next": "n3"}]}, "n3": {"speaker": "roommate2", "text": "Got it, I''ll filter listings with those in mind.", "text_fr": "Compris, je vais filtrer les annonces avec ça en tête.", "choices": [{"text": "Perfect, let''s meet this weekend to review options together.", "text_fr": "Parfait, retrouvons-nous ce week-end pour passer en revue les options ensemble.", "next": "n4"}]}, "n4": {"speaker": "roommate1", "text": "(A few days later) I found three places that look promising, want to see them?", "text_fr": "(Quelques jours plus tard) J''ai trouvé trois endroits qui ont l''air prometteurs, tu veux les voir ?", "choices": [{"text": "Yes, let''s schedule viewings for all three this week.", "text_fr": "Oui, planifions des visites pour les trois cette semaine.", "next": "n5"}]}, "n5": {"speaker": "agent", "text": "Welcome! This unit has two bedrooms and a shared living space, exactly what you''re looking for.", "text_fr": "Bienvenue ! Cette unité a deux chambres et un espace de vie partagé, exactement ce que vous cherchez.", "choices": [{"text": "This looks great! What''s included in the rent exactly?", "text_fr": "Ça a l''air super ! Qu''est-ce qui est inclus dans le loyer exactement ?", "next": "n6"}, {"text": "Nice space — is there flexibility on the move-in date?", "text_fr": "Bel espace — il y a de la flexibilité sur la date d''emménagement ?", "next": "n6b"}]}, "n6": {"speaker": "agent", "text": "Water and trash are included, electricity and internet are separate.", "text_fr": "L''eau et les poubelles sont inclus, l''électricité et internet sont séparés.", "choices": [{"text": "That sounds reasonable, thank you for clarifying.", "text_fr": "Ça semble raisonnable, merci d''avoir clarifié.", "next": "n7"}]}, "n6b": {"speaker": "agent", "text": "We can work with your timeline, within reason — when were you thinking?", "text_fr": "On peut s''adapter à votre calendrier, dans une certaine mesure — vous pensiez à quand ?", "choices": [{"text": "Ideally within the next two months, when our current lease ends.", "text_fr": "Idéalement dans les deux prochains mois, quand notre bail actuel se termine.", "next": "n7"}]}, "n7": {"speaker": "roommate2", "text": "(Whispers) I really like this one, what do you two think?", "text_fr": "(Chuchote) J''aime vraiment celui-là, qu''est-ce que vous en pensez tous les deux ?", "choices": [{"text": "(Whisper back) Same here, it checks all our boxes.", "text_fr": "(Chuchote en retour) Pareil pour moi, ça coche toutes nos cases.", "next": "n8"}, {"text": "I like it too, though I want to see the other two before deciding.", "text_fr": "J''aime bien aussi, même si je veux voir les deux autres avant de décider.", "next": "n8b"}]}, "n8": {"speaker": "roommate1", "text": "Let''s go for it then — should we apply today?", "text_fr": "Allons-y alors — on devrait postuler aujourd''hui ?", "choices": [{"text": "Yes, let''s not risk losing it to someone else.", "text_fr": "Oui, ne risquons pas de le perdre au profit de quelqu''un d''autre.", "next": "n9"}]}, "n8b": {"speaker": "roommate1", "text": "Fair enough, let''s see the other two first before committing.", "text_fr": "Entendu, voyons les deux autres d''abord avant de s''engager.", "choices": [{"text": "(After seeing all three) Actually, this first one really was the best.", "text_fr": "(Après avoir vu les trois) En fait, ce premier était vraiment le meilleur.", "next": "n9"}]}, "n9": {"speaker": "agent", "text": "Great choice! I''ll get the application started for all three of you.", "text_fr": "Excellent choix ! Je démarre la candidature pour vous trois.", "choices": [{"text": "Thank you, this whole process has been smoother than expected.", "text_fr": "Merci, tout ce processus a été plus fluide que prévu.", "next": "n10"}]}, "n10": {"speaker": "roommate2", "text": "I''m honestly really excited about this new chapter together.", "text_fr": "Je suis honnêtement vraiment excité pour ce nouveau chapitre ensemble.", "choices": [{"text": "Same here, I think we make a great team when it comes to this stuff.", "text_fr": "Pareil pour moi, je pense qu''on forme une super équipe pour ce genre de choses.", "next": "n11"}]}, "n11": {"speaker": "roommate1", "text": "Agreed. Now we just need to plan the actual moving logistics!", "text_fr": "D''accord. Maintenant on a juste besoin de planifier la logistique du déménagement !", "choices": [{"text": "One step at a time — we''ll figure that out together too.", "text_fr": "Une étape à la fois — on va aussi trouver ça ensemble.", "next": "end_planned"}]}, "end_planned": {"speaker": "roommate2", "text": "Exactly. This move is going to be a great new start for all of us.", "text_fr": "Exactement. Ce déménagement va être un super nouveau départ pour nous tous.", "end": true, "ending_label": "Déménagement collectif planifié avec succès 📦🏠🎉"}}}'::jsonb, is_playable = true
where title = 'Un déménagement collectif à planifier'
  and theme_id = (select id from scenario_themes where position = 6 and language_id = (select id from languages where code = 'en'));
